(function () {
  'use strict';
  var A = window.App, M = window.MOCK, D = M.discover, t = I18N.t, esc = A.esc, $ = A.$, F = A.Filter, P = A.params;
  var LN = { fr: { fr: 'français', en: 'French' }, en: { fr: 'anglais', en: 'English' } };
  var STATUS = { verified: { cls: 'badge-verified', icon: 'shield-check' }, stale: { cls: 'badge-warn', icon: 'clock' }, unverified: { cls: 'badge-warn', icon: 'alert' } };
  var TYPE_ICON = { api: 'network', sdk: 'code', tool: 'hammer' };
  var form = $('#discover-form'), ctl;

  var SDKN = { go: 'Go', node: 'Node.js', php: 'PHP', python: 'Python', rust: 'Rust' };
  function provClean(r) { return r.provider.replace(/\s*\(fictif\)\s*/, '').replace(/\s*fictif\s*/, ' ').trim(); }
  function slug(s) { return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }
  var CAT = D.items.concat(D.projectItems());
  CAT.forEach(function (r) {
    var c = D.cat(r.category);
    r._prov = provClean(r); r._pslug = slug(r._prov);
    r._hay = [r.name, r.provider, (r.sdk || []).map(function (k) { return k + ' ' + (SDKN[k] || k); }).join(' '), r.summary, r.category, c.fr, c.en, r.type, r.version, r.countries.map(function (x) { return x + ' ' + M.countryName(x); }).join(' ')].join(' ');
    r._n = r.countries.length;
  });

  function lbl(o) { return o[I18N.lang]; }
  function cc(code, id) { return '<span class="country" data-testid="' + id + '"><span class="country-code" data-testid="' + id + '-code">' + code + '</span><span class="visually-hidden" data-testid="' + id + '-name">' + esc(M.countryName(code)) + '</span></span>'; }
  function langBadge(l, id, extra) { var n = LN[l][I18N.lang]; return '<span class="badge" lang="' + I18N.lang + '" data-testid="' + id + '"><span aria-hidden="true" data-testid="' + id + '-code">' + (extra || '') + l.toUpperCase() + '</span><span class="visually-hidden" data-testid="' + id + '-name">' + esc((extra ? t('discover.docs.label') + ' ' : t('common.originalLang') + (I18N.lang === 'fr' ? '\u00a0: ' : ': ')) + n) + '</span></span>'; }
  function providerName(r, p) { return esc(r._prov) + '<span data-proto data-testid="' + p + '-fictional"> · ' + esc(t('discover.fictional')) + '</span>'; }
  function statusBadge(r, id) { var s = D.status(r), o = STATUS[s]; return '<span class="badge ' + o.cls + '" data-testid="' + id + '"><span class="icon i-' + o.icon + '" aria-hidden="true" data-testid="' + id + '-icon"></span>' + esc(t('discover.status.' + s)) + '</span>'; }

  function opts(sel, all, list, keyFn) {
    var cur = sel.value, pre = sel.id + '-option-';   /* option ids: discover-country-option-all | -<value> */
    sel.innerHTML = '<option value="" data-testid="' + pre + 'all">' + esc(all) + '</option>' + list.map(function (x) { return '<option value="' + x.v + '" data-testid="' + pre + x.v + '">' + esc(x.l) + '</option>'; }).join(''); sel.value = cur;
  }
  function fillSelects() {
    var used = {}; CAT.forEach(function (r) { r.countries.forEach(function (c) { used[c] = 1; }); });
    opts($('#discover-country'), t('discover.all.country'), M.countries.filter(function (c) { return used[c.code]; }).map(function (c) { return { v: c.code, l: c.code + ' — ' + lbl(c) }; }));
    opts($('#discover-category'), t('discover.all.category'), D.categories.map(function (c) { return { v: c.id, l: lbl(c) }; }));
    opts($('#discover-type'), t('discover.all.type'), D.types.map(function (c) { return { v: c.id, l: lbl(c) }; }));
    var sd = {}, pv = {}; CAT.forEach(function (r) { (r.sdk || []).forEach(function (k) { sd[k] = 1; }); pv[r._pslug] = r._prov; });
    opts($('#discover-sdk'), t('discover.all.sdk'), Object.keys(sd).sort().map(function (k) { return { v: k, l: SDKN[k] || k }; }));
    opts($('#discover-provider'), t('discover.all.provider'), Object.keys(pv).sort(function (a, b) { return pv[a].localeCompare(pv[b]); }).map(function (k) { return { v: k, l: pv[k] }; }));
    opts($('#discover-doclang'), t('discover.all.doclang'), [{ v: 'fr', l: 'Français (FR)' }, { v: 'en', l: 'English (EN)' }]);
    var s = $('#discover-sort'), cur = s.value || 'verified';
    s.innerHTML = ['verified', 'rating', 'name', 'countries'].map(function (k) { return '<option value="' + k + '" data-testid="discover-sort-option-' + k + '">' + esc(t('discover.sort.' + k)) + '</option>'; }).join(''); s.value = cur;
  }
  function vals() {
    return { q: $('#discover-q').value, country: $('#discover-country').value, category: $('#discover-category').value, type: $('#discover-type').value, doclang: $('#discover-doclang').value, sdk: $('#discover-sdk').value, provider: $('#discover-provider').value, sort: $('#discover-sort').value };
  }
  function active(v) { return !!(v.q || v.country || v.category || v.type || v.doclang || v.sdk || v.provider); }
  function load() {
    var v = vals(), sortMap = { rating: { key: '_rating', dir: 'desc' }, verified: { key: 'verifiedAt', dir: 'desc' }, name: { key: 'name', dir: 'asc' }, countries: { key: '_n', dir: 'desc' } };
    chips(v); strip();
    var res = F.run(CAT, { q: v.q, fields: ['_hay'], where: { countries: v.country, category: v.category, type: v.type, docLang: v.doclang, sdk: v.sdk, _pslug: v.provider }, sort: sortMap[v.sort] });
    /* With no filter the strip already shows the newest projects: don't list them twice. */
    if (!active(v)) { var shown = {}; stripItems().forEach(function (r) { shown[r.id] = 1; }); res = res.filter(function (r) { return !shown[r.id]; }); }
    $('#discover-count').textContent = t(active(v) ? 'discover.count.filtered' : 'discover.count', { n: res.length });
    return res;
  }

  function projectLine(r, p) {
    var parts = t('discover.updatedShort', { d: '\u0000' }).split('\u0000');
    return '<span class="meta-item mono text-sm" data-testid="' + p + '-license">' + esc(r.license) + '</span>' +
      '<span class="meta-item" data-testid="' + p + '-updated">' + esc(parts[0]) + '<time datetime="' + r.updated + '" data-testid="' + p + '-updated-date">' + M.fmtDate(r.updated) + '</time>' + esc(parts[1] || '') + '</span>';
  }
  function pill(r, p) {
    var s = D.status(r);
    return A.statePill(s, { testid: p + '-status', labelKey: 'pill.' + s });
  }
  function row(r, i) {
    var c = D.cat(r.category), p = 'discover-row-' + r.id, proj = r.kind === 'project';
    var vparts = t('discover.verifiedShort', { d: '\u0000' }).split('\u0000');
    return '<li class="row discover-row" data-testid="' + p + '">' +
      '<div class="row-lead">' + A.thumb(r.name, { size: 'md', testid: p + '-thumb' }) + '</div>' +
      '<div class="row-main"><h3 class="row-title"><a href="' + (proj ? r.href : 'resource.html?id=' + r.id) + '" data-testid="' + p + '-link">' + esc(r.name) + '</a>' + (proj ? ' <span class="badge" data-testid="' + p + '-oss"><span class="icon i-git-branch" aria-hidden="true" data-testid="' + p + '-oss-icon"></span>' + esc(t('discover.type.project')) + '</span>' : '') + '</h3>' +
      '<p class="discover-sub" data-testid="' + p + '-provider">' + (proj ? esc(r.provider) : providerName(r, p)) + ' · <span data-testid="' + p + '-category">' + esc(lbl(c)) + '</span>' + (proj ? '' : ' · <span data-testid="' + p + '-type">' + esc(t('discover.type.' + r.type)) + '</span>') + '</p>' +
      '<p class="row-excerpt" lang="' + r.summaryLang + '" data-user-content data-testid="' + p + '-summary">' + esc(r.summary) + '</p>' +
      '<div class="meta discover-meta">' +
        (!proj && r._nrev ? '<span class="meta-item" data-testid="' + p + '-rating-item">' + A.rating(r._rating, { count: r._nrev, testid: p + '-rating' }) + '</span>' : '') +
        '<span class="meta-item" data-testid="' + p + '-countries"><span class="visually-hidden" data-testid="' + p + '-countries-label">' + esc(t('discover.countries.label')) + '</span>' + r.countries.map(function (x) { return cc(x, p + '-country-' + x.toLowerCase()); }).join(' ') + '</span>' +
        (proj ? projectLine(r, p) : '') +
        (r.summaryLang !== I18N.lang ? '<span class="meta-item">' + langBadge(r.summaryLang, p + '-summary-lang') + '</span>' : '') +
      '</div></div>' +
      '<div class="row-aside discover-aside">' + (proj ? A.statePill('open', { testid: p + '-status', label: t('discover.stage.' + r.stage) }) : pill(r, p) +
        (D.status(r) === 'unverified' ? '' : '<span class="discover-when tabular-nums" data-testid="' + p + '-verified">' + esc(vparts[0]) + '<time datetime="' + r.verifiedAt + '" data-testid="' + p + '-verified-date">' + M.fmtDate(r.verifiedAt) + '</time>' + esc(vparts[1] || '') + '</span>')) + '</div></li>';
  }

  function render(items, box) {
    box.innerHTML = '<ul class="list list-reset discover-rows" data-testid="discover-results">' + items.map(row).join('') + '</ul>';
    App.View.apply('discover');
  }

  function stripItems() { return D.projectItems().sort(function (a, b) { return a.updated < b.updated ? 1 : -1; }).slice(0, 4); }
  function strip() {
    var items = stripItems(), box = $('#discover-oss-list');
    box.innerHTML = items.map(function (r) { var p = 'discover-oss-' + r.id;
      return '<li data-testid="' + p + '-item"><a class="card discover-oss-card" href="' + r.href + '" data-testid="' + p + '">' + A.thumb(r.name, { size: 'md', testid: p + '-thumb' }) +
        '<span class="discover-oss-body"><strong data-testid="' + p + '-name">' + esc(r.name) + '</strong><span class="text-sm text-muted discover-oss-sum" lang="' + r.summaryLang + '" data-user-content data-testid="' + p + '-summary">' + esc(r.summary) + '</span>' +
        '<span class="mono text-xs text-muted" data-testid="' + p + '-license">' + esc(r.license) + '</span></span></a></li>'; }).join('');
    $('#discover-oss').hidden = active(vals());
  }

  /* ---- secondary filters disclosure + active chips ---- */
  var more = $('#discover-more'), moreBtn = $('#discover-more-toggle');
  var SEC = ['type', 'provider', 'doclang'];
  function setMore(open) { more.hidden = !open; moreBtn.setAttribute('aria-expanded', open ? 'true' : 'false'); }
  moreBtn.addEventListener('click', function () { setMore(more.hidden); });
  var CHIPS = [['q', 'discover-q', 'discover.chip.q'], ['country', 'discover-country'], ['category', 'discover-category'], ['sdk', 'discover-sdk'], ['type', 'discover-type'], ['provider', 'discover-provider'], ['doclang', 'discover-doclang']];
  function chips(v) {
    var box = $('#discover-chips'), h = '', secActive = false;
    CHIPS.forEach(function (c) {
      var val = v[c[0]]; if (!val) return;
      var lab = c[0] === 'q' ? t(c[2], { l: val }) : ($('#' + c[1] + ' option:checked') || {}).textContent;
      if (SEC.indexOf(c[0]) >= 0) secActive = true;
      h += '<button type="button" class="chip" data-chip="' + c[1] + '" aria-label="' + esc(t('discover.chip.remove', { l: lab })) + '" data-testid="discover-chip-' + c[0] + '"><span data-testid="discover-chip-' + c[0] + '-label">' + esc(lab) + '</span><span class="icon i-x" aria-hidden="true" data-testid="discover-chip-' + c[0] + '-icon"></span></button>';
    });
    if (h) h += '<button type="button" class="btn btn-ghost btn-sm" id="discover-clear" data-testid="discover-clear-button"><span data-testid="discover-clear-label">' + esc(t('discover.clear')) + '</span></button>';
    box.hidden = !h; box.innerHTML = h;
    $('#discover-more-dot').hidden = !secActive;
  }
  function clearAll() { ['q', 'country', 'category', 'sdk', 'type', 'provider', 'doclang'].forEach(function (k) { $('#discover-' + k).value = ''; }); ctl.refresh(); $('#discover-q').focus(); }
  $('#discover-chips').addEventListener('click', function (e) {
    var b = e.target.closest('button'); if (!b) return;
    if (b.id === 'discover-clear') { clearAll(); return; }
    $('#' + b.getAttribute('data-chip')).value = ''; ctl.refresh(); $('#discover-q').focus();
  });

  function applyParams() {
    var map = { q: 'discover-q', country: 'discover-country', category: 'discover-category', type: 'discover-type', doclang: 'discover-doclang', sdk: 'discover-sdk', provider: 'discover-provider', sort: 'discover-sort' };
    Object.keys(map).forEach(function (k) { var x = P.get(k); if (x != null) $('#' + map[k]).value = x; });
  }

  fillSelects(); applyParams(); if (SEC.some(function (k) { return $('#discover-' + k).value; })) setMore(true);
  strip(); ctl = A.Sim.load($('#discover-list'), { load: load, render: render, delay: 600, skeleton: 4, empty: { icon: 'search', key: 'discover.empty', action: { labelKey: 'discover.empty.reset', icon: 'refresh', testid: 'discover-empty-reset', onClick: function () { clearAll(); } } } });
  form.addEventListener('input', function () { ctl.refresh(); });
  form.addEventListener('change', function () { ctl.refresh(); });
  $('#discover-sort').addEventListener('change', function () { ctl.refresh(); });
  form.addEventListener('submit', function (e) { e.preventDefault(); ctl.refresh(); });
  /* just-in-time: country, only when signed in without one (returns null otherwise) */
  App.Session.prompt('country', { container: '#discover-jit', textKey: 'discover.jit.country', testid: 'discover-jit-country',
    onSaved: function () { var u = App.Session.user, sel = $('#discover-country'); if (u && u.country && sel.querySelector('option[value="' + u.country + '"]')) { sel.value = u.country; ctl.refresh(); } } });
  document.addEventListener('i18n:change', function () { fillSelects(); ctl.refresh(); document.title = t('discover.title'); });
  document.title = t('discover.title');
})();
